const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['gemini'], 'AI', 'Chat with Google Gemini', async ({ sock, from, msg, args }) => {
  const prompt = args.join(' ');
  if (!prompt) return sock.sendMessage(from, { text: 'Usage: .gemini <your question>' }, { quoted: msg });
  const key = process.env.GEMINI_API_KEY;
  if (!key) return sock.sendMessage(from, { text: '⚠️ Gemini not set up yet — add GEMINI_API_KEY in .env (free at aistudio.google.com, no card).' }, { quoted: msg });
  try {
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${key}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] })
    });
    const data = await res.json();
    const reply = data.candidates?.[0]?.content?.parts?.[0]?.text || 'No response.';
    await sock.sendMessage(from, { text: reply }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Gemini service unavailable right now.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
